use hos2_os_abi::*;
fn raw(sample:u64, cumulative:u64, start:u64, consumed:u64)->[u8;128] {
    let mut b=[0u8;128];
    b[0..4].copy_from_slice(b"HOSR");
    b[4..6].copy_from_slice(&2u16.to_le_bytes());
    b[8..10].copy_from_slice(&2u16.to_le_bytes());
    b[12..16].copy_from_slice(&64u32.to_le_bytes());
    b[16..20].copy_from_slice(&64u32.to_le_bytes());
    b[24]=1; b[40]=2;
    b[56..64].copy_from_slice(&1u64.to_le_bytes());
    for (i,value) in [sample,cumulative,start,consumed,20_000_000,CPU_PERIOD_NS,0,0].iter().enumerate() {
        b[64+i*8..72+i*8].copy_from_slice(&value.to_le_bytes());
    }
    b
}
fn main() {
    for (sample,cumulative,start,consumed) in [(150_000_000,140_000_000,100_000_000,35_000_000),(1,1,0,0),(100_000_001,100_000_001,100_000_000,0),(1,0,0,0),(1,1,0,1),(1,2,0,0)] {
        let bytes=raw(sample,cumulative,start,consumed);
        let decoded=decode_response(&bytes);
        let physical=cumulative.checked_sub(consumed).is_some_and(|prior| prior<=start);
        let typed=Response{opcode:Opcode::ReadUsage,status:Status::Ok,request_id:[1;16],boot_id:[2;16],revision:1,payload:ResponsePayload::ReadUsage(ReadUsageResponse{sample_boottime_ns:sample,cumulative_cpu_ns:cumulative,window_start_ns:start,window_consumed_ns:consumed,active_cap_ns:20_000_000,active_period_ns:CPU_PERIOD_NS,event_sequence:0,dropped_events:0})};
        println!("sample={sample} cumulative={cumulative} start={start} consumed={consumed} prior_single_cpu_feasible={physical} decode={:?} encode={:?}",decoded.as_ref().map(|_|()),typed.encode(&mut [0u8;128]));
    }
}

