 let mut b=[0u8;128];
 b[..4].copy_from_slice(b"HOSR");b[4..6].copy_from_slice(&2u16.to_le_bytes());b[8..10].copy_from_slice(&4u16.to_le_bytes());b[12..16].copy_from_slice(&64u32.to_le_bytes());b[16..20].copy_from_slice(&64u32.to_le_bytes());b[24]=1;b[40]=2;
 b[64..66].copy_from_slice(&state.as_u16().to_le_bytes());b[66..68].copy_from_slice(&status.as_u16().to_le_bytes());b[72..80].copy_from_slice(&sequence.to_le_bytes());
 let typed=Response{opcode:Opcode::QueryDelivery,status:Status::Ok,request_id:[1;16],boot_id:[2;16],revision:0,payload:ResponsePayload::QueryDelivery(QueryDeliveryResponse{state,saved_status:status,sequence,stable_object_id:[0;16],saved_revision:0,previous_revision:0,effective_ns:0,consumed_ns:0})};
